cypress_script:
describe('Forgotten Login Lookup Form', () => {
  it('should successfully submit valid information', () => {
    cy.visit('https://parabank.parasoft.com/parabank/lookup.htm');
    cy.get('input[id="firstName"]').type('John');
    cy.get('input[id="lastName"]').type('Doe');
    cy.get('input[id="address.street"]').type('123 Main St');
    cy.get('input[id="address.city"]').type('Anytown');
    cy.get('input[id="address.state"]').type('CA');
    cy.get('input[id="address.zipCode"]').type('12345');
    cy.get('input[id="ssn"]').type('123-45-6789');
    cy.get('input[class="button"][value="Find My Login Info"]').click();
    cy.url().should('not.eq', 'https://parabank.parasoft.com/parabank/lookup.htm');
  });

  it('should not submit empty form', () => {
    cy.visit('https://parabank.parasoft.com/parabank/lookup.htm');
    cy.get('input[class="button"][value="Find My Login Info"]').click();
    cy.url().should('eq', 'https://parabank.parasoft.com/parabank/lookup.htm');
    cy.get('div[id="rightPanel"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';
test.describe('Forgotten Login Lookup Form', () => {
  test('should successfully submit valid information', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/lookup.htm');
    await page.fill('input[id="firstName"]', 'John');
    await page.fill('input[id="lastName"]', 'Doe');
    await page.fill('input[id="address.street"]', '123 Main St');
    await page.fill('input[id="address.city"]', 'Anytown');
    await page.fill('input[id="address.state"]', 'CA');
    await page.fill('input[id="address.zipCode"]', '12345');
    await page.fill('input[id="ssn"]', '123-45-6789');
    await page.click('input[class="button"][value="Find My Login Info"]');
    await expect(page).toHaveURL(/^(?!.*lookup.htm).*/);
  });

  test('should not submit empty form', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/lookup.htm');
    await page.click('input[class="button"][value="Find My Login Info"]');
    await expect(page).toHaveURL('https://parabank.parasoft.com/parabank/lookup.htm');
    await expect(page.locator('div[id="rightPanel"]').isVisible());
  });
});
